// --- lib-misp-warninglist, shared block (same text in "Select values" and
// "Result"; pure functions, no calls) -----------------------------------------
// Which observables are checked: a dataType MISP's warninglists know, and none
// of the skip tags (the agent's own observables, internal ranges).
function isEligible(o, w) {
  return w.data_types.includes(o.dataType) && !w.skip_tags.some((t) => o.tags.includes(t));
}
function selectValues(observables, w) {
  return [...new Set(observables.filter((o) => isEligible(o, w)).map((o) => o.data))];
}

// The HTTP node's item -> { ok, class, message, http_status, by_value }.
// MISP answers 200 with an object keyed by the values that match, and with an
// empty array when none does. Anything else is "not done", never "no match".
function parseAnswer(r) {
  const status = typeof r.statusCode === 'number' ? r.statusCode : null;
  if (status === null) { // HTTP node error (On Error = continue): no response
    const e = r.error;
    const detail = typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r);
    const code = `${e?.code ?? e?.cause?.code ?? ''} ${detail}`;
    const unreachable = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ECONNRESET|EHOSTUNREACH|ENETUNREACH|socket hang up|connection cannot be established/i;
    const timeout = /ETIMEDOUT|ECONNABORTED|timeout|timed out/i;
    const cls = unreachable.test(code) ? 'misp_unreachable' : timeout.test(code) ? 'timeout' : 'request_error';
    return { ok: false, class: cls, message: detail.slice(0, 300), http_status: null, by_value: {} };
  }
  if (status !== 200) {
    const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body ?? null);
    return { ok: false, class: `http_${status}`, message: `HTTP ${status}: ${body}`.slice(0, 300), http_status: status, by_value: {} };
  }
  const b = r.body;
  if (Array.isArray(b)) return { ok: true, class: null, message: null, http_status: 200, by_value: {} };
  if (b !== null && typeof b === 'object') return { ok: true, class: null, message: null, http_status: 200, by_value: b };
  return { ok: false, class: 'bad_answer', message: `HTTP 200 without a JSON object or array: ${String(b)}`.slice(0, 300), http_status: 200, by_value: {} };
}

// All list names of one value, in tag order: names containing a `prefer`
// entry first (in `prefer` order), then by name, case-insensitive. Sorted by
// name, not by MISP's order, which follows list ids that differ per instance.
function orderLists(entries, w) {
  const names = [...new Set((Array.isArray(entries) ? entries : [])
    .map((x) => (typeof x?.name === 'string' ? x.name.trim() : '')).filter((n) => n !== ''))];
  const prefer = (w.prefer ?? []).map((p) => String(p).toLowerCase());
  const rank = (n) => { const i = prefer.findIndex((p) => n.toLowerCase().includes(p)); return i === -1 ? prefer.length : i; };
  const cmp = (a, b) => { const x = a.toLowerCase(), y = b.toLowerCase(); return x < y ? -1 : x > y ? 1 : a < b ? -1 : a > b ? 1 : 0; };
  return names.sort((a, b) => rank(a) - rank(b) || cmp(a, b));
}

// Observables + MISP's matches -> the observables with their tags (copies;
// nothing else changes: ioc, severity and status are not this lib's, D12),
// and one entry per matching observable for the writeback.
function applyMatches(observables, byValue, w) {
  const matches = [];
  const out = observables.map((o) => {
    if (!isEligible(o, w) || !Object.prototype.hasOwnProperty.call(byValue, o.data)) return o;
    const lists = orderLists(byValue[o.data], w);
    if (lists.length === 0) return o;
    const wanted = [w.tag, ...lists.slice(0, w.max_list_tags).map((n) => `${w.list_tag_prefix}${n}`)];
    const addTags = wanted.filter((t) => !o.tags.includes(t));
    matches.push({ dataType: o.dataType, data: o.data, lists, add_tags: wanted });
    return { ...o, tags: [...o.tags, ...addTags] };
  });
  return { observables: out, matches };
}

// --- this node: the values to send (pure, no calls) ----------------------------
const i = $input.first().json;
const w = i.config?.misp_warninglist;
if (!w) throw new Error('lib-misp-warninglist needs the lib-config output as `config` (misp_warninglist)');
if (!Array.isArray(i.observables)) throw new Error('lib-misp-warninglist needs `observables` (lib-extract-observables)');
const values = w.enabled === true ? selectValues(i.observables, w) : [];
return [{ json: {
  values, call: values.length > 0,
  skip_reason: w.enabled !== true ? 'disabled' : (values.length === 0 ? 'nothing_eligible' : null),
} }];

