// --- this node: tag the observables, or return them unchanged ------------------
// ok false = the check could not be done (MISP unreachable, timeout, not HTTP
// 200, unreadable answer): the caller continues with the observables as they
// were (C10: "MISP unreachable = continue"). checked false = no call was made.
const i = $('Called by a workflow').first().json;
const w = i.config.misp_warninglist;
const sel = $('Select values').first().json;
const base = { ok: true, checked: false, skip_reason: sel.skip_reason, class: null, message: null, http_status: null,
  observables: i.observables, matches: [],
  counts: { observables: i.observables.length, checked: sel.values.length, matched: 0 } };
if (!sel.call) return [{ json: base }];
const a = parseAnswer($('Check values (MISP)').first().json);
if (!a.ok) return [{ json: { ...base, ok: false, class: a.class, message: a.message, http_status: a.http_status } }];
const { observables, matches } = applyMatches(i.observables, a.by_value, w);
return [{ json: { ...base, checked: true, http_status: 200, observables, matches,
  // matched counts values, like checked (two observables can share a value).
  counts: { ...base.counts, matched: new Set(matches.map((m) => m.data)).size } } }];
